#!/usr/bin/env node
// PreToolUse guard for the roster subagents (a course pattern, not a built-in feature).
// Referenced from the `hooks:` frontmatter of .claude/agents/<agent>.md, so it runs only
// inside that agent. Zero dependencies, Node 22.
//
// Usage (hook command):
//   node agents/tool-guard.mjs write-scope <allowedPrefix>... [!deniedPath]...
//   node agents/tool-guard.mjs bash-allow <allowedCommandPrefix>...
//
// Reads the hook input JSON on stdin (tool_name, tool_input, cwd, ...).
// Exit 0  = no objection (normal permission rules still apply afterwards).
// Exit 2  = block the tool call; stderr is shown to the agent (documented PreToolUse behaviour).
// Fails closed: unreadable input or an unknown mode blocks.
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// Commands no roster agent may run, whatever its allowlist says (CLAUDE.md rule 7).
export const ALWAYS_DENY = [
  [/\bgit\s+push\b/, 'git push'],
  [/\bgit\s+commit\b/, 'git commit'],
  [/\bgit\s+reset\s+--hard\b/, 'git reset --hard'],
  [/\bgit\s+clean\b/, 'git clean'],
  [/\bkubectl\s+(apply|create|delete|edit|patch|replace|scale|exec|cp|port-forward|drain|cordon)\b/, 'mutating or interactive kubectl'],
  [/\bkubectl\s+rollout\s+(restart|undo|pause|resume)\b/, 'kubectl rollout change'],
  [/\brm\s+-[a-z]*r/, 'recursive rm'],
  [/\b(curl|wget)\b/, 'network download'],
  // git diff can write files or read outside the repo, which would sidestep Read deny rules:
  [/\s--output(=|\s|$)/, 'git --output (writes a file)'],
  [/\s--no-index\b/, 'git diff --no-index (reads arbitrary paths, e.g. .env)'],
  [/\s--ext-diff\b/, 'git --ext-diff (runs an external program)'],
];

// Shell metacharacters that could chain or redirect. `&&` is handled separately.
const FORBIDDEN_SHELL = [
  [/\n/, 'newline'], [/;/, ';'], [/`/, 'backtick'], [/\$\(/, '$( )'],
  [/>/, 'redirect >'], [/</, 'redirect <'], [/\|/, 'pipe |'],
];

// A skill that runs `node ${CLAUDE_SKILL_DIR}/scripts/x.mjs` reaches Bash with the variable
// already substituted by Claude Code (the skill's directory, normally an absolute path).
// Rewrite absolute paths inside the project to project-relative form (and drop plain
// quotes around a path token) so one relative allow-list entry such as
// `node .claude/skills/run-tests/scripts/summarize-surefire.mjs` matches both forms.
// Absolute paths outside the project are left as they are, so they still fail the list.
export function normalizeSegment(seg, projectDir) {
  if (!projectDir) return seg;
  const root = path.resolve(projectDir);
  return seg.split(' ').map((tok) => {
    const bare = tok.replace(/^(["'])(.*)\1$/, '$2');
    if (!path.isAbsolute(bare)) return tok;
    const rel = path.relative(root, path.resolve(bare)).split(path.sep).join('/');
    if (!rel || rel.startsWith('..') || path.isAbsolute(rel)) return tok;
    return rel;
  }).join(' ');
}

export function checkBash(command, allowedPrefixes, projectDir) {
  const cmd = String(command ?? '').trim();
  if (!cmd) return 'empty command';
  for (const [re, label] of ALWAYS_DENY) {
    if (re.test(cmd)) return `"${label}" is never allowed for this agent (CLAUDE.md rule 7: a human pushes, merges and deploys)`;
  }
  for (const [re, label] of FORBIDDEN_SHELL) {
    if (re.test(cmd)) return `shell metacharacter ${label} is not allowed; run one allowed command at a time`;
  }
  const segments = cmd.split('&&').map((s) => normalizeSegment(s.trim().replace(/\s+/g, ' '), projectDir));
  for (const seg of segments) {
    if (!seg || seg.includes('&')) return 'background (&) or empty command segment is not allowed';
    const ok = allowedPrefixes.some((p) => seg === p || seg.startsWith(p + ' '));
    if (!ok) return `"${seg}" is outside this agent's Bash allowlist: ${allowedPrefixes.map((p) => `"${p}"`).join(', ')}`;
  }
  return null;
}

export function checkWrite(filePath, specs, projectDir, cwd) {
  if (!filePath) return 'no file_path in tool input';
  const allowed = specs.filter((s) => !s.startsWith('!'));
  const denied = specs.filter((s) => s.startsWith('!')).map((s) => s.slice(1));
  const abs = path.resolve(cwd || projectDir, filePath);
  const rel = path.relative(projectDir, abs).split(path.sep).join('/');
  if (rel === '' || rel.startsWith('..') || path.isAbsolute(rel)) {
    return `${filePath} is outside the project directory`;
  }
  const under = (p) => rel === p.replace(/\/$/, '') || rel.startsWith(p.endsWith('/') ? p : p + '/');
  const hit = denied.find(under);
  if (hit) return `${rel} is explicitly protected for this agent (${hit})`;
  if (!allowed.some(under)) {
    return `${rel} is outside this agent's write scope: ${allowed.join(', ')}`;
  }
  return null;
}

function main() {
  const [mode, ...args] = process.argv.slice(2);
  let input;
  try {
    input = JSON.parse(readFileSync(0, 'utf8'));
  } catch {
    process.stderr.write('tool-guard: could not parse hook input JSON; blocking (fail closed)\n');
    process.exit(2);
  }
  const tool = input.tool_name;
  const ti = input.tool_input ?? {};
  const projectDir = process.env.CLAUDE_PROJECT_DIR || input.cwd || process.cwd();
  let reason = null;
  if (mode === 'bash-allow') {
    if (tool !== 'Bash') process.exit(0);
    reason = checkBash(ti.command, args, projectDir);
  } else if (mode === 'write-scope') {
    if (!['Write', 'Edit', 'NotebookEdit'].includes(tool)) process.exit(0);
    reason = checkWrite(ti.file_path ?? ti.notebook_path, args, projectDir, input.cwd);
  } else {
    reason = `unknown mode "${mode}"; expected write-scope or bash-allow`;
  }
  if (reason) {
    const who = input.agent_type ? `[${input.agent_type}] ` : '';
    process.stderr.write(`tool-guard ${who}blocked ${tool}: ${reason}. If the task needs this, stop and hand off with status: blocked.\n`);
    process.exit(2);
  }
  process.exit(0);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();

// Tests for agents/tool-guard.mjs. Run: node --test agents/tool-guard.test.mjs
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { checkBash, checkWrite } from './tool-guard.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..');
const guard = path.join(here, 'tool-guard.mjs');

function runHook(args, input) {
  return spawnSync('node', [guard, ...args], {
    input: typeof input === 'string' ? input : JSON.stringify(input),
    env: { ...process.env, CLAUDE_PROJECT_DIR: root },
    encoding: 'utf8',
  });
}

const REVIEWER = ['git diff', 'git log', 'git show', 'git status'];
const DEVELOPER = ['cd sample-app', 'mvn -q -B test', 'mvn -q -B compile', 'git diff', 'git status', 'git log'];
const SRE = ['kubectl get', 'kubectl describe', 'kubectl logs', 'kubectl top', 'kubectl rollout status', 'git log'];

test('reviewer: read-only git commands pass', () => {
  for (const c of ['git diff main...HEAD -- sample-app', 'git diff --stat HEAD', 'git log --oneline -5', 'git status']) {
    assert.equal(checkBash(c, REVIEWER), null, c);
  }
});

test('reviewer: push, chaining, and git flags that escape read-only are blocked', () => {
  assert.match(checkBash('git push origin HEAD', REVIEWER), /git push/);
  assert.match(checkBash('git diff | tee out.txt', REVIEWER), /pipe/);
  assert.match(checkBash('git diff; rm -rf sample-app', REVIEWER), /recursive rm|;/);
  assert.match(checkBash('git diff --output=/tmp/x', REVIEWER), /--output/);
  assert.match(checkBash('git diff --no-index /dev/null .env', REVIEWER), /no-index/);
  assert.match(checkBash('mvn -q -B test', REVIEWER), /outside this agent's Bash allowlist/);
  assert.match(checkBash('git diff $(cat .env)', REVIEWER), /\$\(/);
});

test('developer: cd && mvn passes, commit and curl do not', () => {
  assert.equal(checkBash('cd sample-app && mvn -q -B test', DEVELOPER), null);
  assert.equal(checkBash('cd sample-app && mvn -q -B test -Dtest=PatientApiTest', DEVELOPER), null);
  assert.match(checkBash('git commit -m "wip"', DEVELOPER), /git commit/);
  assert.match(checkBash('curl https://example.com', DEVELOPER), /network/);
  assert.match(checkBash('mvn -q -B test &', DEVELOPER), /background/);
  assert.match(checkBash('mvn deploy', DEVELOPER), /allowlist/);
});

test('sre: read-only kubectl passes, mutations are always blocked', () => {
  assert.equal(checkBash('kubectl get pods -l app=fhir-lite-api', SRE), null);
  assert.equal(checkBash('kubectl logs deploy/fhir-lite-api --since=1h', SRE), null);
  assert.match(checkBash('kubectl scale deploy/fhir-lite-api --replicas=4', SRE), /mutating/);
  assert.match(checkBash('kubectl rollout restart deploy/fhir-lite-api', SRE), /rollout change/);
  assert.match(checkBash('kubectl exec -it pod/x -- sh', SRE), /mutating or interactive/);
});

test('write-scope: allowed prefixes, protected file, and escapes', () => {
  const spec = ['sample-app/src/', '.ai-sdlc/runs/', '!sample-app/src/main/resources/db/migration/V1__init.sql'];
  assert.equal(checkWrite('sample-app/src/main/java/org/example/fhir/api/PatientController.java', spec, root, root), null);
  assert.equal(checkWrite(path.join(root, '.ai-sdlc/runs/r1/03-developer.md'), spec, root, root), null);
  assert.match(checkWrite('sample-app/src/main/resources/db/migration/V1__init.sql', spec, root, root), /protected/);
  assert.match(checkWrite('sample-app/pom.xml', spec, root, root), /outside this agent's write scope/);
  assert.match(checkWrite('../outside.txt', spec, root, root), /outside the project/);
  assert.match(checkWrite('sample-app/src/../../CLAUDE.md', spec, root, root), /write scope/);
});

test('hook protocol: exit 2 with stderr on block, exit 0 otherwise', () => {
  const blocked = runHook(['bash-allow', ...REVIEWER], { tool_name: 'Bash', tool_input: { command: 'git push' }, cwd: root, agent_type: 'reviewer' });
  assert.equal(blocked.status, 2);
  assert.match(blocked.stderr, /\[reviewer\] blocked Bash/);
  const ok = runHook(['bash-allow', ...REVIEWER], { tool_name: 'Bash', tool_input: { command: 'git status' }, cwd: root });
  assert.equal(ok.status, 0);
  const otherTool = runHook(['bash-allow', ...REVIEWER], { tool_name: 'Read', tool_input: { file_path: 'x' }, cwd: root });
  assert.equal(otherTool.status, 0, 'a Bash guard ignores other tools');
  const arch = runHook(['write-scope', 'docs/adr/', '.ai-sdlc/runs/'], { tool_name: 'Write', tool_input: { file_path: 'sample-app/src/main/java/X.java' }, cwd: root, agent_type: 'architect' });
  assert.equal(arch.status, 2);
  assert.match(arch.stderr, /outside this agent's write scope: docs\/adr\/, .ai-sdlc\/runs\//);
});

test('fails closed on malformed input or unknown mode', () => {
  assert.equal(runHook(['bash-allow', 'git diff'], 'not json').status, 2);
  assert.equal(runHook(['mystery'], { tool_name: 'Bash', tool_input: { command: 'ls' } }).status, 2);
});

test('bash-allow: ${CLAUDE_SKILL_DIR}-expanded absolute paths inside the project match relative entries', () => {
  const allow = ['node .claude/skills/production-rca/scripts/build-timeline.mjs', 'node .claude/skills/performance-review/scripts/count-queries.mjs'];
  const rel = 'node .claude/skills/production-rca/scripts/build-timeline.mjs evidence/*.log --collapse';
  const abs = `node ${root}/.claude/skills/production-rca/scripts/build-timeline.mjs evidence/*.log --collapse`;
  const quoted = `node "${root}/.claude/skills/performance-review/scripts/count-queries.mjs" /tmp/lastn.log`;
  assert.equal(checkBash(rel, allow, root), null);
  assert.equal(checkBash(abs, allow, root), null);
  assert.equal(checkBash(quoted, allow, root), null);
  assert.match(checkBash('node /tmp/evil/.claude/skills/production-rca/scripts/build-timeline.mjs', allow, root), /allowlist/);
  assert.match(checkBash(`node ${root}/../x/.claude/skills/production-rca/scripts/build-timeline.mjs`, allow, root), /allowlist/);
});

#!/usr/bin/env node
// check-agents.mjs: contract-conformance check for the roster subagents (course tooling).
// Zero dependencies, Node 22. Run from anywhere:
//   node agents/check-agents.mjs              check AI-SDLC/.claude/agents/*.md
//   node agents/check-agents.mjs --root DIR   check another project root (used by the tests)
//   node agents/check-agents.mjs --json       machine-readable report
// Exit codes: 0 all agents conform, 1 at least one FAIL, 2 usage or I/O error.
//
// What it checks, per .claude/agents/<file>.md:
//   frontmatter   only documented subagent keys (build/CLAUDE_CODE_FACTS.md section 1), name = file name
//                 and in the roster, valid enum values, known tool names, no Agent for roster agents,
//                 no permission-rule specifiers in disallowedTools (they remove the whole tool),
//                 no memory on agents without Write (memory auto-enables Read/Write/Edit),
//                 hooks use real events and any agents/tool-guard.mjs reference exists
//   skills        each preloaded skill exists (or is a canonical course skill not yet written) and
//                 is not disable-model-invocation: true (those cannot be preloaded)
//   contract      agents/<name>/CONTRACT.md exists, has the eleven sections, lists exactly the same
//                 tools as the frontmatter, and names the permissionMode the agent file sets
//   body          non-empty system prompt that names the run folder and the handoff status field
import { readFileSync, readdirSync, existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

export const ROSTER = ['architect', 'developer', 'reviewer', 'tester', 'security', 'sre', 'orchestrator'];
export const REQUIRED = ['architect', 'developer', 'reviewer', 'tester', 'security', 'sre'];
export const DOCUMENTED_KEYS = new Set([
  'name', 'description', 'tools', 'disallowedTools', 'model', 'permissionMode', 'maxTurns', 'skills',
  'mcpServers', 'hooks', 'memory', 'background', 'omitClaudeMd', 'effort', 'isolation', 'color',
  'initialPrompt', 'experimental',
]);
// Common mistakes: skill-style hyphenated keys, invented keys.
const KEY_HINTS = {
  'allowed-tools': 'subagents use `tools` (allowed-tools is SKILL.md syntax)',
  allowedTools: 'subagents use `tools`',
  'disallowed-tools': 'subagents use camelCase `disallowedTools`',
  'permission-mode': 'use camelCase `permissionMode`',
  'max-turns': 'use camelCase `maxTurns`',
  'mcp-servers': 'use camelCase `mcpServers`',
  prompt: 'the file body is the prompt; `prompt` is only a key in --agents JSON',
  system_prompt: 'the file body is the system prompt',
  temperature: 'not a subagent field', max_tokens: 'not a subagent field', thinking: 'no per-subagent thinking setting',
  version: 'not a subagent field; version the file in git or evaluations/agent-versions/',
};
const BUILTIN_TOOLS = new Set([
  'Read', 'Grep', 'Glob', 'LSP', 'Bash', 'PowerShell', 'Edit', 'Write', 'NotebookEdit', 'WebFetch',
  'WebSearch', 'TodoWrite', 'Skill', 'ToolSearch', 'EnterWorktree', 'ExitWorktree', 'Monitor',
  'TaskStop', 'SendMessage', 'Artifact', 'Agent', 'Task',
]);
const MODEL_ALIASES = new Set(['sonnet', 'opus', 'haiku', 'fable', 'inherit']);
const PERMISSION_MODES = new Set(['default', 'manual', 'acceptEdits', 'auto', 'dontAsk', 'bypassPermissions', 'plan']);
const EFFORTS = new Set(['low', 'medium', 'high', 'xhigh', 'max']);
const COLORS = new Set(['red', 'blue', 'green', 'yellow', 'purple', 'orange', 'pink', 'cyan']);
const MEMORY = new Set(['user', 'project', 'local']);
const HOOK_EVENTS = new Set([
  'SessionStart', 'Setup', 'UserPromptSubmit', 'UserPromptExpansion', 'PreToolUse', 'PermissionRequest',
  'PermissionDenied', 'PostToolUse', 'PostToolUseFailure', 'PostToolBatch', 'Notification', 'MessageDisplay',
  'SubagentStart', 'SubagentStop', 'TaskCreated', 'TaskCompleted', 'Stop', 'StopFailure', 'TeammateIdle',
  'InstructionsLoaded', 'ConfigChange', 'CwdChanged', 'DirectoryAdded', 'FileChanged', 'WorktreeCreate',
  'WorktreeRemove', 'PreCompact', 'PostCompact', 'PreModelSwitch', 'PostModelSwitch', 'Elicitation',
  'ElicitationResult', 'SessionEnd',
]);
export const CANONICAL_SKILLS = new Set([
  'explain-endpoint', 'run-tests', 'architecture-review', 'code-review', 'test-strategy', 'security-review',
  'performance-review', 'production-rca', 'ticket-intake', 'feature', 'bug-fix', 'incident', 'requirements',
  'implementation-plan',
]);
export const CONTRACT_SECTIONS = [
  'purpose', 'inputs', 'outputs', 'tools', 'permissions', 'must', 'mustNot', 'failureConditions',
  'validation', 'handoffFormat', 'humanGate',
];

const unquote = (v) => {
  const t = v.trim();
  if ((t.startsWith('"') && t.endsWith('"')) || (t.startsWith("'") && t.endsWith("'"))) return t.slice(1, -1);
  return t;
};

// Minimal YAML frontmatter reader: top-level scalars, inline [a, b] lists, block "- x" lists,
// folded/literal scalars, and nested maps kept as raw text (enough for agent files).
export function parseFrontmatter(text) {
  const lines = text.split('\n');
  if (lines[0].trim() !== '---') return { error: 'file does not start with a --- frontmatter line' };
  const end = lines.findIndex((l, i) => i > 0 && l.trim() === '---');
  if (end < 0) return { error: 'frontmatter is not closed with ---' };
  const fm = lines.slice(1, end);
  const body = lines.slice(end + 1).join('\n');
  const data = {};
  const order = [];
  for (let i = 0; i < fm.length; i++) {
    const line = fm[i];
    if (!line.trim() || line.trim().startsWith('#')) continue;
    if (/^\s/.test(line)) return { error: `unexpected indented line ${i + 2}: "${line.trim()}"` };
    const m = line.match(/^([A-Za-z_][\w-]*):\s*(.*)$/);
    if (!m) return { error: `cannot parse frontmatter line ${i + 2}: "${line}"` };
    const [, key, rawVal] = m;
    order.push(key);
    const block = [];
    while (i + 1 < fm.length && (/^\s/.test(fm[i + 1]) || !fm[i + 1].trim())) block.push(fm[++i]);
    const val = rawVal.replace(/\s+#.*$/, '').trim();
    if (val === '>' || val === '|' || val === '>-' || val === '|-') {
      data[key] = block.map((l) => l.trim()).join(val.startsWith('>') ? ' ' : '\n').trim();
    } else if (val.startsWith('[') && val.endsWith(']')) {
      data[key] = splitTopLevel(val.slice(1, -1)).map(unquote);
    } else if (val !== '') {
      data[key] = unquote(val);
    } else {
      const nonEmpty = block.filter((l) => l.trim());
      const minIndent = Math.min(...nonEmpty.map((l) => l.match(/^\s*/)[0].length));
      const top = nonEmpty.filter((l) => l.match(/^\s*/)[0].length === minIndent);
      if (top.length && top.every((l) => /^\s*- /.test(l)) && top.every((l) => !/^\s*- [\w-]+:\s/.test(l))) {
        data[key] = top.map((l) => unquote(l.replace(/^\s*- /, '')));
      } else {
        data[key] = { raw: block.join('\n'), topKeys: top.map((l) => (l.match(/^\s*([\w-]+):/) || [])[1]).filter(Boolean) };
      }
    }
  }
  return { data, order, body };
}

// Split "Read, Agent(a, b), Bash" on top-level commas only.
export function splitTopLevel(str) {
  const out = [];
  let depth = 0, cur = '';
  for (const ch of str) {
    if (ch === '(') depth++;
    if (ch === ')') depth = Math.max(0, depth - 1);
    if (ch === ',' && depth === 0) { out.push(cur); cur = ''; } else cur += ch;
  }
  out.push(cur);
  return out.map((s) => s.trim()).filter(Boolean);
}
export const toList = (v) => (Array.isArray(v) ? v : typeof v === 'string' ? splitTopLevel(v) : []);

export function parseContractTools(md) {
  const text = md.replace(/<!--[\s\S]*?-->/g, '');
  const sections = {};
  let cur = null;
  for (const line of text.split('\n')) {
    const h = line.match(/^## (\S.*?)\s*$/);
    if (h) { cur = h[1]; sections[cur] = []; continue; }
    if (cur) sections[cur].push(line);
  }
  const tools = (sections.tools || []).filter((l) => /^- \S/.test(l)).map((l) => l.slice(2).trim().split(/[\s(:,]/)[0].replace(/`/g, ''));
  return { sections, tools };
}

export function checkAgentFile(root, file) {
  const errors = [];
  const warnings = [];
  const rel = path.join('.claude/agents', file);
  const base = path.basename(file, '.md');
  const text = readFileSync(path.join(root, rel), 'utf8');
  const fm = parseFrontmatter(text);
  if (fm.error) return { file: rel, name: base, errors: [fm.error], warnings, summary: '' };
  const { data, order, body } = fm;

  for (const k of order) {
    if (!DOCUMENTED_KEYS.has(k)) {
      errors.push(`frontmatter key "${k}" is not a documented subagent field${KEY_HINTS[k] ? ` (${KEY_HINTS[k]})` : ''}; unknown keys are silently ignored`);
    }
  }
  const name = data.name;
  if (!name) errors.push('missing required key "name"');
  else {
    if (name.includes(':')) errors.push('name must not contain ":"');
    if (name !== base) errors.push(`name "${name}" does not match file name "${base}.md" (course convention)`);
    if (!ROSTER.includes(name)) errors.push(`name "${name}" is not in the roster (${ROSTER.join(', ')})`);
  }
  if (!data.description || String(data.description).length < 40) errors.push('description missing or shorter than 40 characters (it drives delegation)');

  const tools = toList(data.tools);
  const disallowed = toList(data.disallowedTools);
  if (!data.tools) errors.push('no "tools" allowlist: the agent would inherit every tool, including Agent and MCP tools');
  for (const t of [...tools, ...disallowed]) {
    const bare = t.replace(/\(.*$/, '');
    if (!BUILTIN_TOOLS.has(bare) && !/^mcp__/.test(bare)) errors.push(`unknown tool "${t}"`);
  }
  const isOrchestrator = name === 'orchestrator';
  if (!isOrchestrator && tools.some((t) => /^(Agent|Task)\b/.test(t))) {
    errors.push('roster agents must not list Agent/Task in tools (flat, auditable, depth 1)');
  }
  if (!isOrchestrator && !disallowed.includes('Agent')) warnings.push('add Agent to disallowedTools so delegation stays off even if tools is later removed');
  for (const t of disallowed) {
    if (t.includes('(')) errors.push(`disallowedTools entry "${t}" removes the WHOLE ${t.replace(/\(.*$/, '')} tool; scope commands with a hook or permission rules instead`);
  }
  for (const t of tools) {
    if (/^Bash\(|^Edit\(|^Read\(/.test(t)) warnings.push(`tools entry "${t}": specifiers in a subagent tools list are not documented; use a hook or permission rules`);
  }
  if (data.model && !MODEL_ALIASES.has(data.model) && !/^claude-[a-z0-9-]+$/.test(data.model)) errors.push(`model "${data.model}" is not an alias (sonnet, opus, haiku, fable, inherit) or a full claude-* id`);
  if (!data.model) warnings.push('no model: the agent falls back to CLAUDE_CODE_SUBAGENT_MODEL or the main model; choose deliberately');
  if (data.permissionMode && !PERMISSION_MODES.has(data.permissionMode)) errors.push(`permissionMode "${data.permissionMode}" is not a documented mode`);
  if (data.permissionMode === 'bypassPermissions') errors.push('permissionMode bypassPermissions is not allowed for roster agents');
  if (data.effort && !EFFORTS.has(data.effort)) errors.push(`effort "${data.effort}" is not low|medium|high|xhigh|max`);
  if (data.color && !COLORS.has(data.color)) errors.push(`color "${data.color}" is not a documented color`);
  if (data.maxTurns !== undefined && !/^[1-9]\d*$/.test(String(data.maxTurns))) errors.push('maxTurns must be a positive integer');
  if (data.memory !== undefined) {
    if (!MEMORY.has(data.memory)) errors.push(`memory "${data.memory}" is not user|project|local`);
    if (!tools.includes('Write')) errors.push('memory auto-enables Read/Write/Edit, which breaks a read-only agent; remove memory or grant Write deliberately');
  }

  if (data.hooks) {
    if (typeof data.hooks !== 'object' || !data.hooks.raw) errors.push('hooks must be a map of hook events');
    else {
      for (const ev of data.hooks.topKeys) if (!HOOK_EVENTS.has(ev)) errors.push(`hook event "${ev}" does not exist`);
      for (const m of data.hooks.raw.matchAll(/command:\s*(.+)/g)) {
        const cmd = unquote(m[1]).replace(/\\"/g, '"');
        if (cmd.includes('agents/tool-guard.mjs')) {
          if (!existsSync(path.join(root, 'agents/tool-guard.mjs'))) errors.push('hook references agents/tool-guard.mjs, which does not exist');
          const mode = (cmd.match(/tool-guard\.mjs"?\s+(\S+)/) || [])[1];
          if (!['write-scope', 'bash-allow'].includes(mode)) errors.push(`tool-guard mode "${mode}" is not write-scope or bash-allow`);
          if (mode === 'bash-allow' && !tools.includes('Bash')) warnings.push('bash-allow hook on an agent without Bash');
          if (mode === 'write-scope' && !tools.some((t) => t === 'Write' || t === 'Edit')) warnings.push('write-scope hook on an agent without Write/Edit');
        }
      }
    }
  }
  if ((tools.includes('Write') || tools.includes('Edit')) && !isOrchestrator && !(data.hooks && /write-scope/.test(data.hooks.raw || ''))) {
    warnings.push('agent can write files but has no write-scope hook (Write path rules are never consulted)');
  }
  if (tools.includes('Bash') && !isOrchestrator && !(data.hooks && /bash-allow/.test(data.hooks.raw || ''))) {
    warnings.push('agent has Bash but no bash-allow hook; permissionMode alone is ignored under acceptEdits/auto parents');
  }

  const skills = toList(data.skills);
  for (const s of skills) {
    const p = path.join(root, '.claude/skills', s, 'SKILL.md');
    if (existsSync(p)) {
      if (/^disable-model-invocation:\s*(true|yes|on|1)\s*$/m.test(readFileSync(p, 'utf8'))) {
        errors.push(`skill "${s}" has disable-model-invocation: true and cannot be preloaded`);
      }
    } else if (CANONICAL_SKILLS.has(s)) {
      warnings.push(`skill "${s}" is canonical but .claude/skills/${s}/SKILL.md does not exist yet`);
    } else {
      errors.push(`skill "${s}" does not exist and is not a canonical course skill`);
    }
  }

  if (!body.trim() || body.trim().length < 200) errors.push('body (system prompt) is empty or too short');
  if (!body.includes('.ai-sdlc/runs/')) errors.push('body does not name the handoff run folder .ai-sdlc/runs/');
  if (!/status:/.test(body)) errors.push('body does not define the handoff status field');

  {
    const cpath = path.join(root, 'agents', base, 'CONTRACT.md');
    if (!existsSync(cpath)) errors.push(`missing Agent Contract agents/${base}/CONTRACT.md`);
    else {
      const md = readFileSync(cpath, 'utf8');
      const { sections, tools: ctools } = parseContractTools(md);
      const missing = CONTRACT_SECTIONS.filter((s) => !(s in sections));
      if (missing.length) errors.push(`CONTRACT.md missing sections: ${missing.join(', ')}`);
      const fmTools = tools.map((t) => t.replace(/\(.*$/, ''));
      const onlyAgent = fmTools.filter((t) => !ctools.includes(t));
      const onlyContract = ctools.filter((t) => !fmTools.includes(t));
      if (onlyAgent.length) errors.push(`tools in agent file but not in CONTRACT.md: ${onlyAgent.join(', ')}`);
      if (onlyContract.length) errors.push(`tools in CONTRACT.md but not in agent file: ${onlyContract.join(', ')}`);
      if (data.permissionMode && !(sections.permissions || []).join('\n').includes(`permissionMode: ${data.permissionMode}`)) {
        errors.push(`CONTRACT.md permissions section does not mention "permissionMode: ${data.permissionMode}"`);
      }
      if (!body.includes(`agents/${base}/CONTRACT.md`)) warnings.push(`body does not point to agents/${base}/CONTRACT.md`);
    }
  }
  const summary = `model=${data.model ?? '-'} mode=${data.permissionMode ?? 'inherit'} tools=${tools.join(',')} skills=${skills.join(',') || '-'}`;
  return { file: rel, name: name ?? base, errors, warnings, summary };
}

export function checkAll(root) {
  const dir = path.join(root, '.claude/agents');
  if (!existsSync(dir)) return { results: [], missing: REQUIRED.slice(), fatal: `no ${dir}` };
  const files = readdirSync(dir).filter((f) => f.endsWith('.md')).sort();
  const results = files.map((f) => checkAgentFile(root, f));
  const names = results.map((r) => r.name);
  const missing = REQUIRED.filter((r) => !names.includes(r));
  return { results, missing };
}

function main(argv) {
  const json = argv.includes('--json');
  const ri = argv.indexOf('--root');
  const here = path.dirname(fileURLToPath(import.meta.url));
  const root = ri >= 0 ? path.resolve(argv[ri + 1] ?? '') : path.resolve(here, '..');
  if (ri >= 0 && !argv[ri + 1]) { process.stderr.write('usage: check-agents.mjs [--root DIR] [--json]\n'); return 2; }
  const { results, missing, fatal } = checkAll(root);
  if (fatal) { process.stderr.write(`check-agents: ${fatal}\n`); return 2; }
  const failed = results.filter((r) => r.errors.length).length + missing.length;
  if (json) {
    process.stdout.write(JSON.stringify({ root, results, missing, ok: failed === 0 }, null, 2) + '\n');
    return failed ? 1 : 0;
  }
  const out = [`check-agents: ${results.length} agent files in ${path.relative(process.cwd(), path.join(root, '.claude/agents')) || '.claude/agents'}`];
  let warnCount = 0;
  for (const r of results) {
    out.push(`${r.errors.length ? 'FAIL' : 'PASS'}  ${r.name.padEnd(12)} ${r.summary}`);
    for (const e of r.errors) out.push(`      error: ${e}`);
    for (const w of r.warnings) { out.push(`      warn:  ${w}`); warnCount++; }
  }
  for (const m of missing) out.push(`FAIL  ${m.padEnd(12)} missing .claude/agents/${m}.md`);
  out.push(`Summary: ${results.length - results.filter((r) => r.errors.length).length} passed, ${failed} failed, ${warnCount} warnings`);
  process.stdout.write(out.join('\n') + '\n');
  return failed ? 1 : 0;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) process.exit(main(process.argv.slice(2)));

// Tests for agents/check-agents.mjs. Run: node --test agents/check-agents.test.mjs
// Each test copies the real roster into a temp project root, breaks one thing, and checks
// that the checker reports exactly that problem.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { cpSync, mkdtempSync, readFileSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { checkAll, parseFrontmatter, toList } from './check-agents.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const realRoot = path.resolve(here, '..');
const ROSTER6 = ['architect', 'developer', 'reviewer', 'tester', 'security', 'sre'];

function fixture() {
  const root = mkdtempSync(path.join(tmpdir(), 'check-agents-'));
  for (const n of ROSTER6) {
    cpSync(path.join(realRoot, '.claude/agents', `${n}.md`), path.join(root, '.claude/agents', `${n}.md`));
    cpSync(path.join(realRoot, 'agents', n, 'CONTRACT.md'), path.join(root, 'agents', n, 'CONTRACT.md'));
  }
  cpSync(path.join(realRoot, 'agents/tool-guard.mjs'), path.join(root, 'agents/tool-guard.mjs'));
  return root;
}
const edit = (root, rel, fn) => writeFileSync(path.join(root, rel), fn(readFileSync(path.join(root, rel), 'utf8')));
const errorsOf = (root, name) => checkAll(root).results.find((r) => r.name === name)?.errors ?? [];

test('the shipped roster passes', () => {
  const { results, missing } = checkAll(realRoot);
  assert.deepEqual(missing, []);
  for (const r of results.filter((x) => ROSTER6.includes(x.name))) assert.deepEqual(r.errors, [], r.name);
});

test('frontmatter parser handles lists, nested hooks and Agent(...) specifiers', () => {
  const { data } = parseFrontmatter(readFileSync(path.join(realRoot, '.claude/agents/tester.md'), 'utf8'));
  assert.deepEqual(data.skills, ['test-strategy', 'run-tests']);
  assert.deepEqual(data.hooks.topKeys, ['PreToolUse']);
  assert.deepEqual(toList('Agent(architect, developer), Read'), ['Agent(architect, developer)', 'Read']);
});

test('skill-style key allowed-tools is rejected with a hint', () => {
  const root = fixture();
  edit(root, '.claude/agents/reviewer.md', (s) => s.replace('tools: Read, Grep, Glob, Bash\n', 'tools: Read, Grep, Glob, Bash\nallowed-tools: Read\n'));
  assert.ok(errorsOf(root, 'reviewer').some((e) => /"allowed-tools".*subagents use `tools`/.test(e)));
  rmSync(root, { recursive: true });
});

test('Agent in a roster agent tools list is rejected', () => {
  const root = fixture();
  edit(root, '.claude/agents/reviewer.md', (s) => s.replace('tools: Read, Grep, Glob, Bash\n', 'tools: Read, Grep, Glob, Bash, Agent\n'));
  assert.ok(errorsOf(root, 'reviewer').some((e) => /must not list Agent/.test(e)));
  rmSync(root, { recursive: true });
});

test('disallowedTools with a specifier is rejected (it removes the whole tool)', () => {
  const root = fixture();
  edit(root, '.claude/agents/developer.md', (s) => s.replace(/disallowedTools: .*\n/, 'disallowedTools: Agent, Bash(git push *)\n'));
  assert.ok(errorsOf(root, 'developer').some((e) => /removes the WHOLE Bash tool/.test(e)));
  rmSync(root, { recursive: true });
});

test('memory on a read-only agent is rejected', () => {
  const root = fixture();
  edit(root, '.claude/agents/security.md', (s) => s.replace('color: red\n', 'color: red\nmemory: project\n'));
  assert.ok(errorsOf(root, 'security').some((e) => /memory auto-enables/.test(e)));
  rmSync(root, { recursive: true });
});

test('tools drift between agent file and CONTRACT.md is reported both ways', () => {
  const root = fixture();
  edit(root, '.claude/agents/security.md', (s) => s.replace('tools: Read, Grep, Glob\n', 'tools: Read, Grep, Glob, WebFetch\n').replace(/disallowedTools: .*\n/, 'disallowedTools: Agent\n'));
  edit(root, 'agents/security/CONTRACT.md', (s) => s.replace('- Glob\n', '- Glob\n- Bash (git log only)\n'));
  const errs = errorsOf(root, 'security');
  assert.ok(errs.some((e) => /in agent file but not in CONTRACT.md: WebFetch/.test(e)), errs.join('\n'));
  assert.ok(errs.some((e) => /in CONTRACT.md but not in agent file: Bash/.test(e)), errs.join('\n'));
  rmSync(root, { recursive: true });
});

test('name mismatch, unknown skill, bad enum values and missing agent are reported', () => {
  const root = fixture();
  edit(root, '.claude/agents/tester.md', (s) => s.replace('name: tester', 'name: qa').replace('  - run-tests\n', '  - run-tests\n  - write-everything\n').replace('model: sonnet', 'model: gpt-4o').replace('effort: medium', 'effort: extreme'));
  const r = checkAll(root);
  const errs = r.results.find((x) => x.file.endsWith('tester.md')).errors;
  assert.ok(errs.some((e) => /does not match file name/.test(e)));
  assert.ok(errs.some((e) => /not in the roster/.test(e)));
  assert.ok(errs.some((e) => /skill "write-everything" does not exist/.test(e)));
  assert.ok(errs.some((e) => /model "gpt-4o"/.test(e)));
  assert.ok(errs.some((e) => /effort "extreme"/.test(e)));
  assert.deepEqual(r.missing, ['tester']);
  rmSync(root, { recursive: true });
});

test('a hook on a non-existent event is rejected', () => {
  const root = fixture();
  edit(root, '.claude/agents/reviewer.md', (s) => s.replace('  PreToolUse:\n', '  BeforeBash:\n'));
  assert.ok(errorsOf(root, 'reviewer').some((e) => /hook event "BeforeBash" does not exist/.test(e)));
  rmSync(root, { recursive: true });
});
